/* Схемы перерисованы по показанным в записи. Новые схемы к непоказанным темам не добавляются. */
const DIAGRAM_TOPICS=new Set(['m01','m02','m03','m06','m08','m10','m11','m15','m17','m18','m20','m22','m23']);
const DIAGRAM_CAPTIONS={m01:'Путь S идёт по траектории, а перемещение Δr соединяет начальную точку A и конечную B.',m02:'Разложение ускорения на тангенциальную и нормальную составляющие.',m03:'Угловая скорость и угловое ускорение направлены вдоль оси вращения.',m06:'Брусок скользит вниз по наклонной плоскости: сила трения направлена вверх вдоль плоскости.',m08:'Работа постоянной силы зависит от угла α между силой и перемещением.',m10:'Смещённые оси в теореме Штейнера и геометрическая схема момента силы.',m11:'Работа при малом повороте: dA = Mz dφ.',m15:'Гидравлический пресс и силы тяжести и Архимеда.',m17:'В узкой части горизонтальной трубки скорость выше, а статическое давление ниже.',m18:'Параболический профиль: скорость максимальна в середине трубы и уменьшается к стенкам.',m20:'Математический маятник на нити и груз на пружине.',m22:'Колебание с убывающей по экспоненте амплитудой.',m23:'Резонансные кривые при разном затухании: при меньшем β максимум выше.'};
const CLASSROOM=Object.fromEntries(LESSON_DATA.filter(n=>DIAGRAM_TOPICS.has(n.id)).map(n=>[n.id,{diagram:n.id,caption:DIAGRAM_CAPTIONS[n.id]}]));
function lessonDiagram(id){
 const line=(x1,y1,x2,y2,color='var(--green)',arrow=true)=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${color}" stroke-width="2.5" ${arrow?'marker-end="url(#note-arrow-'+id+')"':''}/>`;
 const text=(x,y,s,color='var(--ink)')=>`<text x="${x}" y="${y}" fill="${color}">${s}</text>`;
 const circle=(x,y,r=6)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="var(--green)"/>`;
 const path=(d,color='var(--green)',dash=false)=>`<path d="${d}" stroke="${color}" stroke-width="2.5" fill="none" ${dash?'stroke-dasharray="7 5"':''}/>`;
 let body='';
 if(id==='m01')body=line(100,215,100,35)+line(100,215,565,215)+line(100,215,165,160)+line(100,215,300,110)+line(165,160,300,110)+path('M165 160 Q205 45 300 110','var(--orange)',true)+circle(165,160)+circle(300,110)+text(80,235,'O')+text(80,35,'Z')+text(575,220,'Y')+text(145,150,'A')+text(310,110,'B')+text(195,175,'Δr = r₂ − r₁')+text(230,55,'Траектория, путь S');
 if(id==='m02')body=path('M75 200 Q185 30 410 140','var(--muted)')+circle(230,105)+line(230,105,390,105)+line(230,105,230,215,'var(--orange)')+line(230,105,355,195)+text(345,90,'v, aτ')+text(200,235,'aₙ')+text(360,205,'a = aτ + aₙ');
 if(id==='m03')body='<ellipse cx="300" cy="170" rx="170" ry="50" fill="none" stroke="var(--green)" stroke-width="2"/>'+line(300,215,300,35)+line(300,170,450,150)+circle(450,150)+text(315,48,'ω, ε — вдоль оси')+text(370,185,'R')+text(125,95,'Направление поворота — правило винта');
 if(id==='m06')body=path('M100 215 L470 95 L470 215 Z','var(--muted)')+'<rect x="270" y="132" width="45" height="38" rx="4" fill="none" stroke="var(--green)" stroke-width="2" transform="rotate(-18 292 150)"/>'+line(292,150,292,235,'var(--orange)')+line(292,150,264,60)+line(292,150,370,125)+text(300,235,'mg')+text(235,55,'N')+text(380,130,'Fтр')+text(145,210,'α');
 if(id==='m08')body=line(95,210,500,210)+line(95,210,395,65,'var(--orange)')+line(95,210,395,210)+path('M160 210 Q165 180 175 173','var(--muted)')+text(410,70,'F')+text(510,215,'S')+text(170,197,'α')+text(205,247,'A = FS cos α');
 if(id==='m10')body='<circle cx="195" cy="132" r="85" fill="none" stroke="var(--green)" stroke-width="2"/><circle cx="225" cy="132" r="55" fill="none" stroke="var(--orange)" stroke-width="2"/>'+line(195,132,225,132)+line(420,190,510,125)+line(510,125,540,45,'var(--orange)')+text(200,120,'a')+text(160,32,'I = Ic + ma²')+text(430,215,'r')+text(545,60,'F')+text(400,245,'M = Fr sin α');
 if(id==='m11')body=line(110,200,470,95)+circle(110,200)+circle(470,95)+line(470,95,510,205,'var(--orange)')+line(470,95,540,70)+text(90,225,'O')+text(280,125,'r')+text(520,210,'F')+text(540,65,'dS = r dφ')+text(180,245,'dA = Mz dφ; Mz = Iz ε');
 if(id==='m15')body=path('M95 60 V210 H310 V60 M95 120 H165 V200 H240 V120 H310')+line(125,30,125,110,'var(--orange)')+line(275,120,275,30)+text(100,25,'F₁')+text(285,30,'F₂')+text(105,150,'S₁')+text(260,135,'S₂')+'<circle cx="485" cy="150" r="42" fill="none" stroke="var(--green)" stroke-width="2"/>'+line(485,145,485,45)+line(485,155,485,235,'var(--orange)')+text(500,50,'FA = ρgV')+text(500,235,'Fт');
 if(id==='m17')body=path('M60 45 H220 Q300 45 370 90 H575 M60 215 H220 Q300 215 370 170 H575')+line(100,130,205,130)+line(410,130,565,130)+text(100,90,'S₁, p₁, v₁')+text(400,65,'S₂, p₂, v₂')+text(155,250,'S₁ > S₂; v₂ > v₁; p₁ > p₂');
 if(id==='m18')body=path('M85 50 H560 M85 220 H560','var(--muted)')+path('M210 50 Q510 135 210 220')+line(85,80,295,80)+line(85,135,355,135)+line(85,190,295,190)+text(375,135,'Профиль скорости')+text(380,160,'v(r) ∼ R² − r²');
 if(id==='m20')body=path('M90 35 H260 M400 35 H530','var(--muted)')+line(175,35,175,210,'var(--muted)',false)+line(175,35,255,185,'var(--green)',false)+circle(255,185,13)+line(255,185,255,245,'var(--orange)')+path('M465 35 V65 l-25 10 50 15 -50 15 50 15 -50 15 50 15 -25 10 v20')+'<rect x="440" y="180" width="50" height="40" rx="5" fill="none" stroke="var(--green)" stroke-width="2"/>'+text(190,120,'l')+text(270,240,'mg')+text(75,260,'T = 2π√(l/g)')+text(400,260,'T = 2π√(m/k)');
 if(id==='m22'){
  const points=[];for(let x=0;x<=490;x+=3)points.push([90+x,130-85*Math.exp(-x/210)*Math.cos(x/17)]);
  body=line(90,245,90,20)+line(70,130,600,130)+path(points.map((p,i)=>(i?'L':'M')+p.join(' ')).join(' '));
  for(const sign of [-1,1])body+=path(Array.from({length:99},(_,i)=>[90+i*5,130+sign*85*Math.exp(-i*5/210)]).map((p,i)=>(i?'L':'M')+p.join(' ')).join(' '),'var(--orange)',true);
  body+=text(60,28,'x')+text(600,150,'t')+text(270,45,'A(t) = A₀ e⁻ᵝᵗ');
 }
 if(id==='m23')body=line(75,235,75,25)+line(75,235,595,235)+path('M75 210 C170 209 240 208 280 175 C310 140 325 42 345 40 C365 42 370 145 410 180 C460 215 535 224 585 229')+path('M75 215 C220 214 245 195 295 155 C300 125 325 125 360 160 C445 205 515 220 585 229','var(--orange)')+path('M360 235 V35','var(--muted)',true)+text(45,30,'A')+text(595,255,'Ω')+text(355,255,'ω₀')+text(390,65,'Малое β₁')+text(430,145,'Большое β₂');
 return `<svg class="lesson-svg" viewBox="0 0 640 285" role="img" aria-label="${esc(CLASSROOM[id]?.caption||'Физическая схема')}"><defs><marker id="note-arrow-${id}" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10Z" fill="context-stroke"/></marker></defs><g font-family="Nunito,sans-serif" font-size="16">${body}</g></svg>`;
}
function classroomScene(t){const data=CLASSROOM[t.id];return data?`<section class="classroom-scene"><h2>Схема</h2><figure>${lessonDiagram(t.id)}<figcaption>${esc(data.caption)}</figcaption></figure></section>`:'';}
